INSERT INTO brands (id, name, slug, selling_point, description, purchase_channels, pickup_methods, rush_difficulty, advance_booking_text, advance_days, release_stock_time, release_stock_day, limit_rules, purchase_notes, contact_info, is_active) VALUES
('brand-001', 'ita cake', 'ita-cake', '独创糯米胚，顶流难抢', 'Ita Cake是上海顶流私房蛋糕，被网友称作"糕圈纯元"，每日限量发售，属于出了名的"难抢款"。主打自研糯米蛋糕胚，搭配斑斓、焙茶、黑芝麻等东方食材，全系列低甜配方，手工打发奶油，不使用工业香精。', '["微信","小程序"]', '["到店自提","同城配送"]', '秒无', '提前1-10天预订', 10, '00:00:00', '每天', '每个ID7天内可预约一个蛋糕。我们将移除用以交易的订单及账号', '选择的日期与时间为需要蛋糕当日的发货时间，蛋糕无法提前出货，请不要提前取货', '18017345279（11:00-19:00在线）', 1),
('brand-002', 'tinyroll', 'tinyroll', '茶味 + 鲜果 + 紫苏油戚风胚，低甜不腻，压倒性好评', '上海顶流私房蛋糕，每周日1点小程序开抢一分钟售罄，号称蛋糕天花板。主打茶味 + 鲜果组合，招牌紫苏玄米蜜瓜用紫苏油戚风胚配玄米奶油。', '["小程序"]', '["预约后堂食","到店自提","同城配送"]', '秒无', '提前7天预订', 7, '13:00:00', '周日', NULL, NULL, NULL, 1),
('brand-003', '胡团CAKE', 'hutuan', '咸甜猎奇巴斯克，高端猎奇', '胡团是上海近期话题度最高的私房蛋糕之一，走高端猎奇路线，靠白松露、法葱、正荣开心果等小众食材出圈，咸甜巴斯克是招牌。', '["小程序"]', '["到店自提","同城配送"]', '有货', '提前20小时预订', 5, NULL, '随机', NULL, '官方微信：Hutuan_studio', NULL, 1),
('brand-004', 'sillage', 'sillage', '热带水果茶味低甜路线', '"魔都小蛋糕天花板"，门店 + 小程序预约，提前1天可订，生日蛋糕友好。品类丰富，配料走热带水果 + 茶味低甜路线。', '["小程序","大众/美团"]', '["到店自提","5km内配送"]', '有货', '提前1-3天预订', 1, NULL, NULL, NULL, '客服微信：13162666830', NULL, 1),
('brand-005', '向野制果', 'xiangye', '从社区小店到全上海4家门店，招牌巴斯克年化坪效12万/平', '向野制果从茅台路第一家社区小店起步，发展到全上海布局四家门店，年化坪效达12万元/平方米。招牌巴斯克蛋糕。', '["微信小程序","美团","饿了么","到店"]', '["到店自提","同城配送","团购免邮"]', '热门', '提前1天预订', 1, '10:30:00', '随机', '蛋糕手工现做数量有限，想要品尝可得趁早', '13916641917（茅台路店）', NULL, 1),
('brand-006', 'wakuwaku', 'wakuwaku', '前身是热门店Huizi，搭配大胆', 'Wakuwaku前身是"上海最难预订的糕店"Huizi，沉寂大半年后改名回归，配料走猎奇复合风味路线。', '["小程序"]', '["到店自提","同城配送"]', '热门', '提前7天预订', 7, '15:00:00', '每天', '蛋糕挞类布丁每款限购一个', NULL, '客服微信：18117539653', 1),
('brand-007', 'pournil', 'pournil', '法式甜品小店，巴斯克可全城送', 'POURNIL糕点铺是上海静安区的法式甜品小店，主营巴斯克蛋糕、法式甜品等，可全城配送。', '["微信","小程序","到店"]', '["到店自提","同城配送","全城送"]', '有货', '提前1-3天预订', 2, '10:30:00', '每天', '巴斯克为冷藏甜品，不宜长时间加热', '15800313766', NULL, 1),
('brand-008', 'toris', 'toris', '东京主厨出品，杨枝甘露蛋糕成名，低糖不腻', 'Toris由两位资深媒体人创立，由日本东京蛋糕师出品，品牌名源自Tokyo+Paris，追求和风与法式甜点融合。', '["微信小程序","饿了么","美团","到店"]', '["到店自提","同城配送"]', '热门', '提前1-3天预订', 2, '00:00:00', '每天', '蛋糕需冷藏保存，室温放置过久奶油会融化', '18616720695（陆家嘴店）', NULL, 1),
('brand-009', 'haku', 'haku', '永康路日系复古蛋糕店，需拿号等位', 'Haku白一制菓位于徐汇区永康路，是日系复古风格的网红蛋糕甜品店，工作日下午也要排队。', '["到店","微信","小程序"]', '["到店自提","同城配送"]', '热门', '提前1-2天预订', 1, '11:00:00', '每天', '需要拿号等位，座位保留10分钟', NULL, NULL, 1),
('brand-010', '矿野野', 'yeyeland', '矿物甜品概念店，像宝石博物馆，可拍迷你小人照', '矿野野矿物甜品概念店位于徐汇区乌鲁木齐南路，2026年新开，甜品造型如矿物宝石。', '["到店","微信"]', '["到店自提"]', '热门', NULL, NULL, NULL, NULL, '拍照需点宝石蛋糕加咖啡套餐，迷你小人照限时15分钟', NULL, NULL, 1),
('brand-011', '瑭所', 'tangsuo', '中式美学蛋糕，宋代美学+海派基因，美到不舍得吃', '瑭所诞生于2023年8月，将中式美学凝练于食与礼之间，蛋糕如古诗词般美丽。', '["到店","微信","小程序"]', '["到店自提","同城配送"]', '热门', '提前1-3天预订', 2, '10:00:00', '每天', '玉兰冰蛋糕的糖片较甜，食用时可拨开部分', NULL, NULL, 1),
('brand-012', 'Butter', 'butter', 'Butter%百分百，经典抹茶系列+季节限定', 'Butter%（Butter百分百）是上海人气甜品店，经典抹茶系列是招牌，季节限定款也很受欢迎。', '["到店","微信","小程序"]', '["到店自提","同城配送"]', '热门', NULL, NULL, NULL, NULL, '各门店营业时间和产品供应可能不同，建议到店前确认', '15800661101（武夷路店）', NULL, 1),
('brand-013', 'pensee', 'pensee', '老洋行里的法式甜品，造型如艺术品', 'Pensee法式甜品位于静安区延平路，把老上海工业遗存的复古肌理和法式甜品的细腻恰到好处地融合。', '["到店","微信"]', '["到店自提"]', '有货', NULL, NULL, NULL, NULL, '门店位置较隐蔽，建议提前电话或微信确认营业状态', NULL, NULL, 1),
('brand-014', 'yeetlemon', 'yeetlemon', '主打柠檬蛋糕，做酸跟甜的平衡', 'Yeetlemon柠檬蛋糕是上海主打柠檬风味的蛋糕店，品牌理念清晰：柠檬蛋糕做酸跟甜的平衡。', '["到店","微信","小程序"]', '["到店自提","同城配送"]', '有货', NULL, NULL, NULL, NULL, '两家门店通用券；柠檬蛋糕酸度较高', '18930031610', NULL, 1),
('brand-015', 'His Aroma', 'his-aroma', '米其林一星甜点主厨坐镇，老洋行里的甜品实验室', 'His Aroma Patisserie隐藏在虹口区1913老洋行里，店主曾是米其林一星餐厅的甜点主厨。', '["到店","微信"]', '["到店自提"]', '有货', NULL, NULL, NULL, NULL, '仅周三至周日营业，周一二闭店', NULL, NULL, 1),
('brand-016', 'Onform', 'onform', '久光百货新开甜品店，拿破仑+水果蛋糕', 'OnForm是久光百货新开的甜品店，海报款拿破仑吸引眼球。', '["到店"]', '["到店自提"]', '有货', NULL, NULL, NULL, NULL, '蛋糕建议回温后食用', NULL, NULL, 1),
('brand-017', 'APPLE PICKER', 'apple-picker', '2019年起手工烘焙，衡山路梧桐树下的甜品展厅', 'The Apple Picker从2019年起坚持手工制作烘焙点心与生日蛋糕、时令果酱等产品。', '["微信","小程序","到店"]', '["到店自提","同城配送"]', '有货', '提前1-2天预订', 1, '11:00:00', '每天', '店内仅设一张堂食桌，建议打包带走', NULL, NULL, 1),
('brand-018', 'EAU CAFE', 'eau-cafe', '法式复古咖啡馆，面包+蛋糕，买面包送咖啡', 'EAU CAFE是上海法式复古风格的咖啡馆，多家门店。新店开业有活动，买任意蛋糕面包收藏打卡送一杯咖啡。', '["到店","微信"]', '["到店自提","同城配送"]', '有货', NULL, NULL, NULL, NULL, '各门店营业时间可能不同，建议到店前确认', '021-61376598（武夷路店）', NULL, 1),
('brand-019', 'SEE THEE', 'see-thee', '莎士比亚十四行诗命名，从线上工作室到洋房蛋糕屋', 'SEE THEE店名来自莎士比亚十四行诗里的see thee，原本是一家只做蛋糕预约的甜品工作室。', '["微信","小程序","到店"]', '["到店自提","同城配送"]', '热门', '提前1-2天预订', 1, '11:00:00', '每天', '周一闭店，仅周二至周日营业', '18501638313', NULL, 1),
('brand-020', 'Connie He', 'connie-he', '精品烘焙品牌，甜品颜值能打，奶香浓郁甜度刚好', 'ConnieHe笑屋是上海精品烘焙品牌，甜品颜值能打，每一款都让人忍不住想拍照。', '["到店","微信","小程序"]', '["到店自提","同城配送"]', '热门', '提前1-2天预订', 1, '10:00:00', '每天', '各门店营业时间可能不同，建议到店前确认', '13391087618（吴兴路店）', NULL, 1),
('brand-021', '聚福', 'jufu', '复古怀旧上海风，咸蛋黄流心千层是招牌', '聚福Shanghailander位于五原路，是复古怀旧风格的蛋糕店，招牌蛋黄流心千层。', '["到店","微信"]', '["到店自提"]', '热门', NULL, NULL, NULL, NULL, '咸蛋黄流心千层的咸蛋黄可能较咸', NULL, NULL, 1);
